"""Generate theme assets from tokens.json; --check reports drift without writes."""
import argparse
import json
import re
from pathlib import Path


def kebab(name):
    name = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1-\2", name)
    return re.sub(r"([a-z0-9])([A-Z])", r"\1-\2", name).lower()


def render(data):
    theme = {"token": data["token"], "components": {"Menu": data["menu"]}}
    login = {**data["token"], **data["login"]}
    ts = (
        "// Generated by scripts/build_tokens.py from assets/tokens.json.\n"
        "import type { ThemeConfig } from 'antd';\n\n"
        f"export const proTheme = {json.dumps(theme, ensure_ascii=False, indent=2)} satisfies ThemeConfig;\n\n"
        f"export const loginTheme = {{ token: {json.dumps(login, ensure_ascii=False, indent=2)} }} satisfies ThemeConfig;\n"
    )
    css = ["/* Generated from tokens.json; apply .antd-design-system to the application shell. */", ".antd-design-system {"]
    for key, value in data["token"].items():
        if isinstance(value, (int, float)) and key != "lineHeight":
            value = f"{value}px"
        css.append(f"  --ds-{kebab(key)}: {value};")
    for key, value in data["layout"].items():
        css.append(f"  --ds-{kebab(key)}: {value}px;")
    for value in data["spacing"]:
        css.append(f"  --ds-space-{value}: {value}px;")
    css += ["}", ".antd-design-system.ds-login, .antd-design-system .ds-login {"]
    for key, value in data["login"].items():
        css.append(f"  --ds-{kebab(key)}: {value};")
    css += ["}", ""]
    return {"antd-theme.ts": ts, "design-tokens.css": "\n".join(css)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    assets = Path(__file__).resolve().parents[1] / "assets"
    data = json.loads((assets / "tokens.json").read_text(encoding="utf-8"))
    mismatched = []
    for name, content in render(data).items():
        target = assets / name
        if args.check:
            if not target.exists() or target.read_text(encoding="utf-8") != content:
                mismatched.append(name)
        else:
            target.write_text(content, encoding="utf-8", newline="\n")
    if mismatched:
        raise SystemExit("Outdated generated assets: " + ", ".join(mismatched))
    print("Token assets match." if args.check else "Generated theme and CSS tokens.")


if __name__ == "__main__":
    main()
